if (!bin) throw new Error('Missing binary img. Check HTTP Request: Response Format=File, Binary Property Name=img');

// IMPORTANT: read real bytes (fixes "filesystem-v2")
const buf = await this.helpers.getBinaryDataBuffer(0, 'img');
const imgBase64 = buf.toString('base64');

// Fix mimeType: your file is .webp
const mimeType = 'image/webp';

// Build Gemini request body
const basePrompt = item.json.basePrompt || 'Replace background with a premium studio setup and add packaging props.';
const prompt =
  `Use the provided product image as the only source of truth.
Keep the product geometry and design identical.
Do NOT redraw the product. Do not change the gemstone cut, prongs, metal thickness, chain links, engraving, or proportions.

Retouch like a luxury jewelry e-commerce studio shot:
- Background: pure white (#FFFFFF), seamless.
- Exposure: high-key, clean whites without clipping product highlights.
- Lighting: two large softboxes left/right + gentle top light, soft but crisp shadow directly under the pendant (contact shadow).
- Materials: realistic metal reflections, sharp edges, micro-contrast, no plastic look, no over-smoothing.
- Output: very sharp, clean, realistic, minimal noise, no text, no watermark, no CGI, no 3D render.
Composition: centered, product fills ~70% of frame height, symmetrical.
Shadow: a subtle soft gray shadow under the product, no floating.
Color: neutral white balance, accurate metal color, accurate gemstone color.
Edges: crisp anti-aliased edges, no jagged edges.

`;

return [{
  json: {
    geminiBody: {
      contents: [{
        parts: [
          { text: prompt },
          { inlineData: { mimeType, data: imgBase64 } }
        ]
      }],
      generationConfig: { responseModalities: ['TEXT', 'IMAGE'] }
    }
  }
}];

const res = $input.first().json;

// 找到第一個有 inlineData 的 part（就是圖片）
const parts = res?.candidates?.[0]?.content?.parts ?? [];
const imgPart = parts.find(p => p.inlineData?.data);

if (!imgPart) throw new Error('No inlineData image found in Gemini response');

const mimeType = imgPart.inlineData.mimeType || 'image/png';
const data = imgPart.inlineData.data; // base64 string

const ext = mimeType.split('/')[1] || 'png';

return [{
  json: { mimeType },
  binary: {
    gen: {
      data,
      mimeType,
      fileName: `scene.${ext}`
    }
  }
}];

